function supportAt(x,z){let top=0;for(let b of house.solids){let t=b.y+b.h;if(t<1.13&&Math.abs(x-b.x)<b.w/2+.13&&Math.abs(z-b.z)<b.d/2+.13)top=Math.max(top,t)}return top}
function updateJump(dt){let floor=supportAt(house.x,house.z),grounded=house.jumpHeight<=floor+.025&&house.jumpVelocity<=0;if(!house.keys[' '])house.jumpLatch=false;if(house.keys[' ']&&!house.jumpLatch){if(grounded)house.jumpVelocity=5.2;house.jumpLatch=true}if(house.jumpVelocity!==0||house.jumpHeight>floor){let old=house.jumpHeight;house.jumpVelocity-=10*dt;house.jumpHeight+=house.jumpVelocity*dt;if(house.jumpHeight>1.12){house.jumpHeight=1.12;house.jumpVelocity=Math.min(0,house.jumpVelocity)}if(house.jumpHeight<=floor){house.jumpHeight=floor;house.jumpVelocity=0}if(old!==house.jumpHeight)house.dirty=true}}
const sanityHUD=document.createElement('div');sanityHUD.className='sanity-hud';const sanityTitle=document.createElement('div'),sanityBar=document.createElement('progress'),sandwichStatus=document.createElement('small');sanityBar.max=100;sanityBar.setAttribute('aria-label','Sanity');sanityHUD.append(sanityTitle,sanityBar,sandwichStatus);gameScene.append(sanityHUD);const sanityEffect=document.createElement('div');sanityEffect.className='sanity-impact';gameScene.append(sanityEffect);let impactTimer,lastSanitySave=0;
function sanityState(){if(!Number.isFinite(s.sanity))s.sanity=100;if(!Number.isFinite(s.sandwichAt))s.sandwichAt=0;return s.sanity}
function sanityDisplay(){sanityState();sanityTitle.textContent='SANITY '+Math.ceil(s.sanity)+'%';sanityBar.value=s.sanity;const seconds=Math.max(0,Math.ceil((s.sandwichAt-Date.now())/1000));sandwichStatus.textContent=seconds?'Sandwich refill: '+Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0'):'Kitchen sandwich: ready (+12%)'}
function sanityLoss(){s.sanity=0;s.sanityLost=true;house.keys={};save();modal('YOU LOST: YOUR SANITY GOT CONSUMED','The house has taken the last piece of you.',[['Start again',()=>reset()]])}
function drainSanity(amount){if(s.ending||s.sanityLost)return;sanityState();const loss=Math.min(s.sanity,amount);s.sanity=Math.max(0,s.sanity-loss);if(loss>2){clearTimeout(impactTimer);sanityEffect.classList.remove('hit');void sanityEffect.offsetWidth;sanityEffect.classList.add('hit');tone(34,1);impactTimer=setTimeout(()=>sanityEffect.classList.remove('hit'),3000)}sanityDisplay();if(s.sanity===0)sanityLoss()}
function eatSandwich(){sanityState();if(s.sandwichAt>Date.now()){modal('The plate is empty','A fresh sandwich will appear when the two-minute refill timer finishes.',[['Back',close]]);return}if(s.sanity>=100){modal('You feel steady','Your sanity is already full. Leave the sandwich for later.',[['Back',close]]);return}s.sanity=Math.min(100,s.sanity+12);s.sandwichAt=Date.now()+120000;save();render();sanityDisplay();say('You eat a sandwich. Sanity restored by 12%, up to 100%. The plate refills in two minutes.')}
function queueSanity(amount){s.pendingSanity=(s.pendingSanity||0)+amount;save()}
const sanityClose=close;close=function(){sanityClose();const pending=s.pendingSanity||0;s.pendingSanity=0;if(pending){drainSanity(pending);save()}};
const sanityDiary=diary;diary=function(){let first=!s.read;sanityDiary();if(first){queueSanity(8)}};
const sanityDiscovery=discovery;discovery=function(flag,...args){let first=!flags()[flag];sanityDiscovery(flag,...args);if(first){queueSanity(({mirror:15,ward:12,letter:6,code:4,called:9,power:5,truth:10})[flag]||3)}};
const sanityAct=act;act=function(obey){let first=!s.acted;sanityAct(obey);if(first){drainSanity(obey?5:9);save()}};
const sanityInspect=inspect;inspect=function(item){let first=!s.seen.includes(item);sanityInspect(item);if(first){queueSanity(item==='tape'?5:3)}};
const sanityMovement=updateMovement;updateMovement=function(dt){sanityMovement(dt);if(!s.ending&&!s.sanityLost){drainSanity(dt/30);if(performance.now()-lastSanitySave>5000){lastSanitySave=performance.now();save()}}sanityDisplay()};
const sanityTargets=targets;targets=function(){return sanityTargets().concat([{name:'Kitchen sandwiches',p:[-4.1,.84,7.8],fn:eatSandwich}])};
const sanitySurface=surface;surface=function(t){if(t.name!=='Kitchen sandwiches')return sanitySurface(t);return [[-4.4,.84,7.55],[-3.8,.84,7.55],[-3.8,.84,8.05],[-4.4,.84,8.05]]};
const sanityBuild=buildHouse;buildHouse=function(){sanityBuild();house.solids.push({x:5.65,z:7.6,w:2,d:3,y:0,h:.8});box(-4.1,.825,7.8,.6,.012,.5,'#b9b59a');if(Date.now()>=(s.sandwichAt||0)){box(-4.1,.84,7.8,.28,.04,.25,'#c8ab75');box(-4.1,.88,7.8,.28,.015,.25,'#668247');box(-4.1,.895,7.8,.28,.035,.25,'#d6bb86')}};
let plateReady=Date.now()>=(s.sandwichAt||0);setInterval(()=>{if(paused()||s.ending||s.sanityLost)return;sanityDisplay();let ready=Date.now()>=(s.sandwichAt||0);if(ready!==plateReady){plateReady=ready;buildHouse();house.dirty=true}},1000);
const sanityReset=reset;reset=function(){s.pendingSanity=0;clearTimeout(impactTimer);sanityEffect.classList.remove('hit');sanityReset();s.sanity=100;s.sanityLost=false;s.sandwichAt=0;save();sanityDisplay()};
sanityState();if(s.sandwichAt>Date.now()+120000){s.sandwichAt=Date.now()+120000;save()}render();sanityDisplay();if(s.sanityLost||s.sanity===0)sanityLoss();
